<template>
  <main class="identity-page">
    <h1>库存身份</h1>
    <p>登记明确的货权、原始用途和产品技术身份。独立确认后可供业务选择；实际库存变动仍需通过相应业务校验。</p>
    <p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
    <section v-if="pending" class="recovery"><p>有一笔提交结果待确认，请先查询原操作。</p><button :disabled="busy" @click="recover(false)">查询原操作</button><button :disabled="busy" @click="recover(true)">关闭未提交原操作</button></section>
    <form @submit.prevent="reload(1)"><label>记录类型<select v-model="kind" aria-label="记录类型" :disabled="busy"><option value="PARTY">货权主体</option><option value="PURPOSE">原始用途</option><option value="PRODUCT">产品身份</option></select></label><label>编号搜索<input v-model="search" aria-label="编号搜索" maxlength="128" /></label><button :disabled="busy">查询记录</button></form>
    <p><button :disabled="busy || page === 1" @click="reload(page - 1)">上一页</button>第 {{ page }} 页<button :disabled="busy || rows.length < 20" @click="reload(page + 1)">下一页</button><button :disabled="locked || !can('add')" @click="create">新建记录</button></p>
    <ul><li v-for="row in rows" :key="row.reference.id"><button :disabled="busy" @click="open(row.reference.id)">{{ row.original.definition.code }} · {{ row.original.definition.name }}</button> {{ state(row.original.state) }} · v{{ row.reference.version }}</li></ul>
    <section v-if="definition">
      <h2>{{ current ? '记录详情' : '新建记录' }}</h2>
      <p v-if="current">{{ state(current.original.state) }} · v{{ current.reference.version }} · {{ current.canSelect ? '当前可以选择' : '当前不可选择，请检查来源或确认状态' }}</p>
      <form @submit.prevent="save('SAVE')">
        <fieldset :disabled="locked || !can(current ? 'edit' : 'add')">
          <label>编号<input v-model="definition.code" aria-label="身份编号" :disabled="!!current" maxlength="64" required /></label>
          <label>名称<input v-model="definition.name" aria-label="身份名称" maxlength="200" required /></label>
          <label>登记依据<textarea v-model="definition.basis" aria-label="登记依据" maxlength="4000" required /></label>
          <label v-if="creation">所属部门<select v-model="department" aria-label="所属部门" required><option v-if="creation.allowsUnbound" value="unbound">不绑定部门</option><option v-else disabled value="">请选择当前可用部门</option><option v-for="d in creation.departments" :key="d.id" :value="d.id">{{ d.code }} · {{ d.name }}</option></select></label>
          <template v-if="definition.party">
            <label>货权类型<select v-model="definition.party.kind" aria-label="货权类型" :disabled="!!current" required @change="partyChanged"><option disabled value="">请明确选择</option><option value="SELF">自有法律主体</option><option value="CUSTOMER">客户所有</option></select></label>
            <template v-if="definition.party.kind === 'SELF'"><label>法律主体名称<input v-model="definition.party.legalName" aria-label="法律主体名称" required maxlength="200" /></label><label>注册管辖地<input v-model="definition.party.jurisdiction" aria-label="注册管辖地" :disabled="!!current" required maxlength="64" /></label><label>登记号码<input v-model="definition.party.registrationNumber" aria-label="登记号码" :disabled="!!current" required maxlength="100" /></label><p>填写明确的法律主体资料，由另一位有权人员确认。</p></template>
            <template v-else-if="definition.party.kind === 'CUSTOMER'"><label>客户编号搜索<input v-model="sourceSearch" aria-label="客户搜索" maxlength="20" /></label><button type="button" @click="findCustomers(1)">查询客户</button><label>准确客户<select :value="refKey(definition.party.customer)" aria-label="准确客户" required @change="chooseCustomer"><option value="">请选择真实客户</option><option v-if="definition.party.customer && !customers.some(c => refKey(c.reference) === refKey(definition!.party!.customer))" :value="refKey(definition.party.customer)">已保存的准确客户 v{{ definition.party.customer.version }}</option><option v-for="c in customers" :key="refKey(c.reference)" :value="refKey(c.reference)">{{ c.source.bpCd }} · {{ c.source.bpName }} · v{{ c.reference.version }}</option></select></label><button type="button" :disabled="customerPage === 1" @click="findCustomers(customerPage - 1)">上一批客户</button><button type="button" :disabled="customerPage * 20 >= customerTotal" @click="findCustomers(customerPage + 1)">下一批客户</button></template>
          </template>
          <template v-if="definition.purpose"><label>原始用途<select v-model="definition.purpose.category" aria-label="原始用途" :disabled="!!current" required><option disabled value="">请明确选择</option><option value="TRIAL">试制</option><option value="PRODUCTION">量产来源</option><option value="OTHER">其他明确用途</option></select></label><label>用途含义<textarea v-model="definition.purpose.meaning" aria-label="用途含义" maxlength="2000" required /></label><p>原始用途不表示当前生产准入资格。</p></template>
          <template v-if="definition.kind === 'PRODUCT'">
            <label>工程产品搜索<input v-model="sourceSearch" aria-label="工程产品搜索" maxlength="100" /></label><button type="button" @click="findEngineering(1)">查询工程产品</button>
            <button v-for="e in engineering" :key="e.reference.id" type="button" @click="findMappings(e.reference.id, 1)">{{ e.product.code }} · {{ e.product.name }}</button>
            <button type="button" :disabled="engineeringPage === 1" @click="findEngineering(engineeringPage - 1)">上一批工程产品</button><button type="button" :disabled="engineering.length < 20" @click="findEngineering(engineeringPage + 1)">下一批工程产品</button>
            <label>双 Owner 已确认映射<select :value="refKey(definition.product?.mapping)" aria-label="准确产品映射" required @change="chooseMapping"><option value="">请选择准确映射</option><option v-if="definition.product && !mappings.some(m => refKey(m.reference) === refKey(definition!.product!.mapping))" :value="refKey(definition.product.mapping)">已保存映射 v{{ definition.product.mapping.version }}</option><option v-for="m in mappings" :key="refKey(m.reference)" :value="refKey(m.reference)">{{ m.candidate.purpose }} · {{ m.candidate.businessRef?.id }} · v{{ m.reference.version }}</option></select></label>
            <button type="button" :disabled="mappingPage === 1" @click="findMappings(engineeringId, mappingPage - 1)">上一批映射</button><button type="button" :disabled="!moreMappings" @click="findMappings(engineeringId, mappingPage + 1)">下一批映射</button>
            <template v-if="definition.product">
              <p>产品 v{{ definition.product.product.version }} · 单位绑定 v{{ definition.product.unitBinding.version }}</p>
              <label>技术身份<select v-model="definition.product.technicalKind" aria-label="技术身份" required @change="definition.product.baseline = null"><option disabled value="">请明确选择</option><option value="KNOWN">使用已冻结技术基线</option><option value="NOT_APPLICABLE">技术版本不适用，需明确依据及确认</option></select></label>
              <template v-if="definition.product.technicalKind === 'KNOWN'"><button type="button" @click="findBaselines(1)">查询冻结基线</button><label>准确冻结基线<select :value="refKey(definition.product.baseline)" aria-label="准确冻结基线" required @change="chooseBaseline"><option value="">请选择真实冻结基线</option><option v-if="definition.product.baseline && !baselines.some(b => refKey(b.reference) === refKey(definition!.product!.baseline))" :value="refKey(definition.product.baseline)">已保存基线 {{ definition.product.baseline.id }}</option><option v-for="b in baselines" :key="b.reference.id" :value="refKey(b.reference)">{{ b.reference.id }} · {{ b.original.frozenAt }}</option></select></label><button type="button" :disabled="baselinePage === 1" @click="findBaselines(baselinePage - 1)">上一批基线</button><button type="button" :disabled="!moreBaselines" @click="findBaselines(baselinePage + 1)">下一批基线</button></template>
              <label>技术适用性依据<textarea v-model="definition.product.technicalBasis" aria-label="技术适用性依据" maxlength="4000" required /></label>
              <template v-for="category in (['PARTY', 'PURPOSE'] as const)" :key="category"><label>{{ category === 'PARTY' ? '货权编号搜索' : '用途编号搜索' }}<input v-model="identitySearch[category]" :aria-label="category + '搜索'" maxlength="128" /></label><button type="button" @click="findIdentities(category, 1)">{{ category === 'PARTY' ? '查询已确认货权' : '查询已确认用途' }}</button><label>{{ category === 'PARTY' ? '准确货权主体' : '准确原始用途' }}<select :value="refKey(category === 'PARTY' ? definition.product.party : definition.product.purpose)" :aria-label="category + '选择'" required @change="chooseIdentity(category, $event)"><option value="">请选择已确认记录</option><option v-if="category === 'PARTY' ? definition.product.party : definition.product.purpose" :value="refKey(category === 'PARTY' ? definition.product.party : definition.product.purpose)">已选准确记录</option><option v-for="v in identityChoices[category]" :key="refKey(v.reference)" :value="refKey(v.reference)">{{ v.original.definition.code }} · {{ v.original.definition.name }} · v{{ v.reference.version }}</option></select></label><button type="button" :disabled="identityPage[category] === 1" @click="findIdentities(category, identityPage[category] - 1)">上一批{{ category === 'PARTY' ? '货权' : '用途' }}</button><button type="button" :disabled="!moreIdentity[category]" @click="findIdentities(category, identityPage[category] + 1)">下一批{{ category === 'PARTY' ? '货权' : '用途' }}</button></template>
            </template>
          </template>
          <button>保存草稿</button>
        </fieldset>
        <label>操作原因<textarea v-model="reason" aria-label="操作原因" maxlength="4000" required :disabled="locked" /></label>
      </form>
      <p v-if="current"><button :disabled="locked || dirty || !can('approve') || current.original.state !== 'DRAFT' || current.original.authorId === scope?.actorId" @click="save('APPROVE')">独立确认</button><button :disabled="locked || !can('disable') || current.original.state === 'DISABLED'" @click="save('DISABLE')">停用记录</button><button v-if="current.original.definition.kind === 'PRODUCT'" :disabled="busy || !current.canSelect" @click="readCatalogue">核对业务选项</button></p>
      <p v-if="catalogue">{{ catalogue.option.label }} · {{ catalogue.option.technicalIdentity.kind === 'KNOWN' ? '已绑定冻结基线' : '不适用依据已确认' }} · 实际库存业务校验仍需执行。</p>
      <form v-if="current" @submit.prevent="readHistory"><label>历史版本<input v-model="historyVersion" aria-label="历史版本" pattern="[1-9][0-9]*" required /></label><button :disabled="busy">读取历史</button></form>
      <article v-if="history"><h3>历史 v{{ history.reference.version }}</h3><p>{{ history.original.definition.name }} · {{ state(history.original.state) }}</p><details><summary>查看保存原件</summary><pre>{{ history.originalJson }}</pre></details></article>
    </section>
  </main>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { inventoryIdentityApi as api, type IdentityScope, type IdentityCreation, type IdentityDefinition, type IdentityView, type IdentityRef, type IdentityCommand, type IdentityCatalogue, type CustomerIdentity } from '@/api/wms/inventoryIdentities'
import { engineeringApi, type EngineeringVersion, type MappingVersion } from '@/api/plm/engineeringProducts'
import { baselineApi, type BaselineView } from '@/api/plm/engineeringBaselines'
import { productUnitApi } from '@/api/erp/uomProfiles'
import { identityResponse as result, pendingInventoryIdentity, saveInventoryIdentity, resolveInventoryIdentity, type PendingInventoryIdentity } from '@/auth/inventoryIdentityRecovery'
import { AUTH_EVENT, identityStamp, requireIdentity } from '@/auth/identity'
import { authenticationCanRead } from '@/auth/browserAuthentication'
import { usePermissionStore } from '@/stores/permission'
const permission = usePermissionStore(), can = (action: string) => permission.has('wms-inventory-identity:' + action)
const scope = ref<IdentityScope | null>(null), pending = ref<PendingInventoryIdentity | null>(null), busy = ref(false), error = ref(''), notice = ref(''), locked = computed(() => busy.value || !!pending.value)
const kind = ref<IdentityDefinition['kind']>('PARTY'), search = ref(''), page = ref(1), rows = ref<IdentityView[]>([]), current = ref<IdentityView | null>(null), definition = ref<IdentityDefinition | null>(null), objectId = ref(''), creation = ref<IdentityCreation | null>(null), department = ref(''), reason = ref('')
const sourceSearch = ref(''), customers = ref<CustomerIdentity[]>([]), customerPage = ref(1), customerTotal = ref(0), engineering = ref<EngineeringVersion[]>([]), engineeringPage = ref(1), engineeringId = ref(''), mappings = ref<MappingVersion[]>([]), mappingPage = ref(1), moreMappings = ref(false), baselines = ref<BaselineView[]>([]), baselinePage = ref(1), moreBaselines = ref(false)
const identityChoices = ref<Record<'PARTY' | 'PURPOSE', IdentityView[]>>({ PARTY: [], PURPOSE: [] }), identitySearch = ref({ PARTY: '', PURPOSE: '' }), identityPage = ref({ PARTY: 1, PURPOSE: 1 }), moreIdentity = ref({ PARTY: false, PURPOSE: false })
const dirty = computed(() => !!current.value && JSON.stringify(definition.value) !== JSON.stringify(current.value.original.definition))
const historyVersion = ref('1'), history = ref<IdentityView | null>(null), catalogue = ref<IdentityCatalogue | null>(null)
const copy = <T,>(v: T): T => JSON.parse(JSON.stringify(v)) as T, refKey = (r?: IdentityRef | null) => r ? `${r.id}:${r.version}:${r.digest}` : ''
const state = (s: string) => ({ DRAFT: '待独立确认', APPROVED: '已确认', DISABLED: '已停用' })[s] || '状态待核实'
let live = true, generation = 0
function clearEditor() { current.value = null; definition.value = null; creation.value = null; reason.value = ''; objectId.value = ''; department.value = ''; history.value = null; catalogue.value = null; customers.value = []; engineering.value = []; mappings.value = []; baselines.value = []; identityChoices.value = { PARTY: [], PURPOSE: [] }; sourceSearch.value = ''; engineeringId.value = ''; identitySearch.value = { PARTY: '', PURPOSE: '' } }
function clearPrivate() { clearEditor(); scope.value = null; pending.value = null; rows.value = []; search.value = '' }
async function run(action: (check: () => void) => Promise<void>) {
  if (busy.value) return; const stamp = identityStamp(), epoch = generation
  const check = () => { requireIdentity(stamp); if (!live || generation !== epoch || !authenticationCanRead()) throw new Error('当前身份已变化。') }
  busy.value = true; error.value = ''; notice.value = ''
  try { check(); await action(check); check() }
  catch (e: any) { try { check(); const status = e?.response?.status; if ([401, 403].includes(status)) clearPrivate(); error.value = [401, 403].includes(status) ? '当前无权读取或操作身份及其来源。' : status === 412 ? '准确版本已变化，请查询原操作后重新打开记录。' : e?.response ? '请核对输入、来源和确认权限，查询原操作后重试。' : e?.message || '暂无法确认结果。' } catch { /* Discard a previous identity response. */ } }
  finally { try { check(); pending.value = scope.value ? pendingInventoryIdentity(scope.value) : null; busy.value = false } catch { if (live && generation === epoch) busy.value = false } }
}
async function reload(next = 1) { await run(async check => { clearEditor(); rows.value = []; if (!permission.loaded) await permission.loadMyActions(); check(); const s = result(await api.scope()); check(); scope.value = s; const values = result(await api.list(kind.value, search.value, next)); check(); rows.value = values; page.value = next }) }
function edit(v: IdentityView) { clearEditor(); current.value = v; definition.value = copy(v.original.definition); objectId.value = v.reference.id }
async function open(id: string) { await run(async check => { clearEditor(); const v = result(await api.read(id)); check(); edit(v) }) }
async function create() { await run(async check => { if (!can('add') || pending.value) throw new Error('请先完成原操作并确认创建权限。'); clearEditor(); const c = result(await api.creation()); check(); creation.value = c; department.value = c.allowsUnbound ? 'unbound' : ''; objectId.value = crypto.randomUUID(); definition.value = { kind: kind.value, code: '', name: '', basis: '', party: kind.value === 'PARTY' ? { kind: '', legalName: null, jurisdiction: null, registrationNumber: null, customer: null } : null, purpose: kind.value === 'PURPOSE' ? { category: '', meaning: '' } : null, product: null } }) }
function partyChanged() { const p = definition.value?.party; if (p) { p.legalName = p.jurisdiction = p.registrationNumber = null; p.customer = null } }
const selected = (e: Event) => (e.target as HTMLSelectElement).value
async function findCustomers(next: number) { await run(async check => { customers.value = []; const v = result(await api.customers(sourceSearch.value, next)); check(); customers.value = v.items.filter(c => c.isCurrent && c.projection === 'FULL' && c.source.customerFlg && !c.source.isDeleted && !c.source.isFrozen); customerTotal.value = v.total; customerPage.value = next }) }
function chooseCustomer(e: Event) { const c = customers.value.find(c => refKey(c.reference) === selected(e)); if (definition.value?.party) definition.value.party.customer = c ? copy(c.reference) : null }
async function findEngineering(next: number) { await run(async check => { engineering.value = []; const v = result(await engineeringApi.list(sourceSearch.value, next)); check(); engineering.value = v; engineeringPage.value = next }) }
async function findMappings(id: string, next: number) { await run(async check => { if (!id) throw new Error('请先选择工程产品。'); mappings.value = []; const v = result(await engineeringApi.mappings(id, next)); check(); engineeringId.value = id; mappings.value = v.filter(m => m.canAdoptIdentitySite); mappingPage.value = next; moreMappings.value = v.length === 20 }) }
async function chooseMapping(e: Event) { const m = mappings.value.find(m => refKey(m.reference) === selected(e)); await run(async check => { if (!m?.candidate.businessRef || !definition.value) throw new Error('请从真实映射列表选择。'); const unit = result(await productUnitApi.read(m.candidate.businessRef.id)); check(); if (!unit.currentApplicable || unit.productVersion !== m.candidate.businessRef.version || unit.productDigest !== m.candidate.businessRef.digest) throw new Error('产品单位绑定或映射已变化，请先补齐来源。'); if (current.value?.original.definition.product?.product.id && current.value.original.definition.product.product.id !== m.candidate.businessRef.id) throw new Error('产品身份不可替换，请新建记录。'); definition.value.product = { product: copy(m.candidate.businessRef), mapping: copy(m.reference), unitBinding: { owner: 'Main.Erp.ProductUnit.v1', id: unit.productId, version: unit.version, digest: unit.digest }, technicalKind: '', technicalBasis: '', baseline: null, party: null, purpose: null }; engineeringId.value = m.candidate.engineeringRef.id }) }
async function findBaselines(next: number) { await run(async check => { baselines.value = []; if (!definition.value?.product) return; const mapping = result(await engineeringApi.mapping(definition.value.product.mapping.id, definition.value.product.mapping.version)); check(); const v = result(await baselineApi.list(next)); check(); baselines.value = v.filter(b => b.sourceStatus === 'CURRENT' && refKey(b.original.revision.draft.productRef) === refKey(mapping.candidate.engineeringRef)); baselinePage.value = next; moreBaselines.value = v.length === 20 }) }
function chooseBaseline(e: Event) { const b = baselines.value.find(b => refKey(b.reference) === selected(e)); if (definition.value?.product) definition.value.product.baseline = b ? copy(b.reference) : null }
async function findIdentities(category: 'PARTY' | 'PURPOSE', next: number) { await run(async check => { identityChoices.value[category] = []; const v = result(await api.list(category, identitySearch.value[category], next)); check(); identityChoices.value[category] = v.filter(v => v.canSelect); identityPage.value[category] = next; moreIdentity.value[category] = v.length === 20 }) }
function chooseIdentity(category: 'PARTY' | 'PURPOSE', e: Event) { const v = identityChoices.value[category].find(v => refKey(v.reference) === selected(e)); if (definition.value?.product) definition.value.product[category === 'PARTY' ? 'party' : 'purpose'] = v ? copy(v.reference) : null }
async function save(action: IdentityCommand['action']) { await run(async check => { if (!scope.value || !definition.value || !objectId.value || !reason.value.trim() || !can(action === 'SAVE' ? current.value ? 'edit' : 'add' : action === 'APPROVE' ? 'approve' : 'disable')) throw new Error('请补全操作原因并确认当前权限。'); if (action !== 'SAVE' && !current.value) throw new Error('请先保存草稿。'); if (action === 'APPROVE' && dirty.value) throw new Error('请先保存修改，再确认准确版本。'); if (action === 'SAVE' && definition.value.kind === 'PRODUCT') { const p = definition.value.product; if (!p || !p.party || !p.purpose || !['KNOWN', 'NOT_APPLICABLE'].includes(p.technicalKind) || (p.technicalKind === 'KNOWN' && !p.baseline)) throw new Error('请先选择真实产品映射、货权、用途及明确技术身份。') }; const c = { id: objectId.value, action, expectedVersion: current.value?.reference.version || 'absent', definition: action === 'SAVE' ? copy(definition.value) : null, reason: reason.value, expectedAuthorityVersion: creation.value?.authorityVersion || null, departmentId: creation.value && department.value !== 'unbound' ? department.value : null }; await saveInventoryIdentity(scope.value, c.id, check, operationId => api.save({ ...c, operationId })); check(); clearEditor(); const v = result(await api.read(c.id)); check(); edit(v); notice.value = action === 'APPROVE' ? '独立确认已保存。' : action === 'DISABLE' ? '身份已停用，历史原件保留。' : '草稿已保存，新的内容需要独立确认。' }) }
async function recover(close: boolean) { await run(async check => { if (!scope.value) return; const v = await resolveInventoryIdentity(scope.value, close, check); check(); if (v.state === 'COMMITTED' && v.result) { clearEditor(); const original = result(await api.read(v.result.objectId)); check(); edit(original); notice.value = '已找回原操作。' } else notice.value = v.state === 'CLOSED' ? '未提交原操作已关闭。' : '结果仍未知，请继续查询原操作。' }) }
async function readHistory() { await run(async check => { if (!current.value) return; const v = result(await api.read(current.value.reference.id, historyVersion.value)); check(); history.value = v }) }
async function readCatalogue() { await run(async check => { if (!current.value) return; catalogue.value = null; const v = result(await api.catalogue(current.value.reference)); check(); catalogue.value = v }) }
function reset() { generation++; busy.value = false; clearPrivate(); if (authenticationCanRead()) void reload() }
watch(kind, reset); onMounted(() => { window.addEventListener(AUTH_EVENT, reset); void reload() }); onBeforeUnmount(() => { live = false; generation++; clearPrivate(); window.removeEventListener(AUTH_EVENT, reset) })
</script>
<style scoped>
.identity-page{max-width:1050px;margin:auto;padding:24px}.identity-page section,.identity-page fieldset{padding:18px;margin:16px 0;border:1px solid #cbd5df;border-radius:8px}.identity-page label{display:flex;flex-direction:column;gap:5px;margin:12px 0}.identity-page input,.identity-page select,.identity-page textarea{padding:8px;max-width:760px}.identity-page button{margin:5px;padding:7px 12px}.identity-page pre{white-space:pre-wrap;overflow-wrap:anywhere}.recovery{background:#fff7dc}[role=alert]{color:#a32626}
</style>
